$ErrorActionPreference='SilentlyContinue';$c=Get-CimInstance Win32_ComputerSystem;$a=@(Get-CimInstance Win32_PhysicalMemoryArray | Where-Object { $_.Use -eq 3 });$m=@(Get-CimInstance Win32_PhysicalMemory);[pscustomobject]@{Auto=[string]$c.AutomaticManagedPagefile;Slots=[string](($a | Measure-Object MemoryDevices -Sum).Sum);Used=[string]$m.Count;MaxKB=[string](($a | Measure-Object MaxCapacityEx -Sum).Sum);Installed=[string](($m | Measure-Object Capacity -Sum).Sum)} | ConvertTo-Json -Compress